changeSet.sql:
DELETE FROM cocktail_steps cs USING cocktail c, step s WHERE cs.cocktail_id = c.id AND cs.steps_id = s.id AND c.name IN ('Daiquiri', 'Margarita', 'Mojito', 'Negroni', 'Old Fashioned') AND s.goal IN ('Охладить бокал', 'Смешать ингредиенты', 'Подать');
INSERT INTO step (goal, description) VALUES ('Влить ром, лайм и сироп', 'Добавить ингредиенты в шейкер со льдом.'), ('Встряхнуть', 'Энергично встряхивать до охлаждения и перелить в охлаждённый бокал.'), ('Украсить лаймом', 'Добавить тонкий кружок лайма и подать.'), ('Подготовить бокал', 'Смочить край лаймом и покрыть его солью.'), ('Встряхнуть с текилой', 'Добавить текилу, апельсиновый ликёр, лайм и лёд в шейкер.'), ('Процедить в бокал', 'Встряхнуть до охлаждения и процедить в подготовленный бокал.'), ('Размять мяту', 'Мягко прижать мяту с лаймом и сиропом, не измельчая листья.'), ('Добавить ром и лёд', 'Влить ром, заполнить бокал льдом и аккуратно перемешать.'), ('Долить содовую', 'Добавить содовую, перемешать и украсить веточкой мяты.'), ('Соединить ингредиенты', 'Налить джин, Campari и сладкий вермут в стакан со льдом.'), ('Перемешать со льдом', 'Перемешать барной ложкой до охлаждения напитка.'), ('Украсить апельсином', 'Процедить на свежий лёд и добавить апельсиновую цедру.'), ('Растворить сахар', 'Размять сахарный кубик с биттером и несколькими каплями воды.'), ('Добавить бурбон', 'Влить бурбон и положить крупный кубик льда.'), ('Перемешать и подать', 'Перемешать до охлаждения, украсить цедрой и подать.');
INSERT INTO cocktail_steps (cocktail_id, steps_id) SELECT c.id, s.id FROM (VALUES ('Daiquiri', 'Влить ром, лайм и сироп'), ('Daiquiri', 'Встряхнуть'), ('Daiquiri', 'Украсить лаймом'), ('Margarita', 'Подготовить бокал'), ('Margarita', 'Встряхнуть с текилой'), ('Margarita', 'Процедить в бокал'), ('Mojito', 'Размять мяту'), ('Mojito', 'Добавить ром и лёд'), ('Mojito', 'Долить содовую'), ('Negroni', 'Соединить ингредиенты'), ('Negroni', 'Перемешать со льдом'), ('Negroni', 'Украсить апельсином'), ('Old Fashioned', 'Растворить сахар'), ('Old Fashioned', 'Добавить бурбон'), ('Old Fashioned', 'Перемешать и подать') ) AS recipe_steps(cocktail_name, step_goal) JOIN cocktail c ON c.name = recipe_steps.cocktail_name JOIN step s ON s.goal = recipe_steps.step_goal WHERE NOT EXISTS ( SELECT 1 FROM cocktail_steps cs WHERE cs.cocktail_id = c.id AND cs.steps_id = s.id );
